{
  "primary_meaning": "Typological foreshadowing of Christ's death, burial, and resurrection (three days in the heart of the earth)",
  "primary_basis": [
    "Matthew 12:39-41",
    "Matthew 16:4",
    "Luke 11:29-32",
    "Jonah 1:17",
    "Jonah 2:1-10"
  ],
  "alternatives": [
    {
      "meaning": "Image of Sheol/the grave or the realm of death from which God delivers",
      "basis": [
        "Jonah 2:2",
        "Jonah 2:6",
        "Psalm 18:4-6"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Instrument of divine judgment, discipline, and providential rescue/mercy",
      "basis": [
        "Jonah 1:17",
        "Jonah 2:10",
        "Psalm 107:23-30"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Chaos monster or embodiment of primordial evil/disorder (linked to Leviathan/Rahab traditions)",
      "basis": [
        "Job 41",
        "Psalm 74:13-14",
        "Isaiah 27:1",
        "Isaiah 51:9"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "Primarily literal historical creature in a didactic narrative with minimal inherent symbolism",
      "basis": [
        "Jonah 1–2"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "In historic Christian teaching the dominant reading is Christological typology grounded in Jesus' own reference to Jonah; other senses (Sheol, providence, chaos) appear regularly but remain secondary or complementary rather than rival primary meanings."
}
